import java.util.*;import java.util.concurrent.*;class Solution{static List<Integer> map(List<Integer>values)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);try{List<CompletableFuture<Integer>>futures=values.stream().map(value->CompletableFuture.supplyAsync(()->value*2,pool)).toList();return futures.stream().map(CompletableFuture::join).toList();}finally{pool.shutdown();if(!pool.awaitTermination(5,TimeUnit.SECONDS))pool.shutdownNow();}}}
